/**
 * Pencil + halftone dinosaur plates for the marketing site.
 *
 * The eight plates are generated by `pnpm gen:art` (scripts/gen-dino-art.mjs)
 * into `*.svelte` files next to this module; `Dino.svelte` is the hand-written
 * wrapper that adds the in-view draw animation and micro-motions.
 */
export const DINO_NAMES = [
  'rex',
  'stego',
  'trike',
  'brachio',
  'ptero',
  'fossil',
  'egg',
  'tracks'
] as const;

export type DinoName = (typeof DINO_NAMES)[number];

export { default as Dino } from './Dino.svelte';
